    float bval = 0.0f;
    if (B != nullptr && gco < CO) {
      bval = (float)B[gco];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[co][i] = bval;
    }
  }

  const int in_d0 = d0 - (K - 1);
  const int in_h0 = h0 - (K - 1);
  const int in_w0 = w0 - (K - 1);
  // 16B-aligned halo staging: pad the halo row width to HWP and shift the
  // global column origin down to a multiple of 4 floats (16 bytes).
  const int aw0  = in_w0 & ~3;
  const int woff = in_w0 - aw0;
  const bool vec_ok = ((Wid & 3) == 0);

  // Double-buffered asynchronous pipeline: stage the next input-channel
  // chunk into shared memory (async copies) while computing on the current one.
  auto stage_load = [&](int buf, int ci_base) {
    if (vec_ok) {
      // 16B-aligned path: one thread stages one padded halo row (HWP floats)
      // with four 16-byte cp.async transactions (scalar tail at borders).
      constexpr int X_ROWS = CI_CHUNK * HD * HH;
      for (int row = tid; row < X_ROWS; row += Threads) {
        int ci = row / (HD * HH);
        int rem = row - ci * (HD * HH);
        int hd = rem / HH;
        int hh = rem - hd * HH;
        int gci = ci_base + ci;
        int id  = in_d0 + hd;
        int ih  = in_h0 + hh;
        T* dst = sX_raw[buf] + row * HWP;
        if (gci < CI && (unsigned)id < (unsigned)D && (unsigned)ih < (unsigned)H) {
          const T* src = &mX(gci, id, ih, 0) + aw0;
          #pragma unroll
          for (int v = 0; v < HWP / 4; ++v) {
            const int iw = aw0 + v * 4;
            if (iw >= 0 && iw + 4 <= Wid) {
              __pipeline_memcpy_async(dst + v * 4, src + v * 4, sizeof(T) * 4);
            } else {
              #pragma unroll
              for (int j = 0; j < 4; ++j) {
                const int iwj = iw + j;
                dst[v * 4 + j] = ((unsigned)iwj < (unsigned)Wid) ? src[v * 4 + j] : T(0);
              }
            }
          }
        } else {
          #pragma unroll
          for (int v = 0; v < HWP; ++v) dst[v] = T(0);
        }
      }
    } else {
      // Generic path for widths that are not multiples of 4: scalar 4B cp.async.
      constexpr int X_ELEMS = CI_CHUNK * HD * HH * HWP;
      for (int idx = tid; idx < X_ELEMS; idx += Threads) {
        int ci = idx / (HD * HH * HWP);
        int rem = idx - ci * (HD * HH * HWP);
        int hd = rem / (HH * HWP);
        rem -= hd * (HH * HWP);
        int hh = rem / HWP;
        int hw = rem - hh * HWP;
        int gci = ci_base + ci;
        int id  = in_d0 + hd;
        int ih  = in_h0 + hh;
        int iw  = aw0 + hw;
        T* dst = sX_raw[buf] + idx;
        if (gci < CI &&
            (unsigned)id < (unsigned)D &&
            (unsigned)ih < (unsigned)H &&
            (unsigned)iw < (unsigned)Wid) {
          __pipeline_memcpy_async(dst, &mX(gci, id, ih, iw), sizeof(T));
        } else {
          *dst = T(0);
        }
      }
    }
    constexpr int W_ELEMS = CI_CHUNK * CO_TILE * K * K * K;
    for (int idx = tid; idx < W_ELEMS; idx += Threads) {
      int ci = idx / (CO_TILE * K * K * K);
      int rem = idx - ci * (CO_TILE * K * K * K);
      int co = rem / (K * K * K);
      rem -= co * (K * K * K);
      int kd = rem / (K * K);
      rem -= kd * (K * K);
      int kh = rem / K;
      int kw = rem - kh * K;
      int gci = ci_base + ci;
      int gco = co0 + co;
      T* dst = sW_raw[buf] + idx;
      if (gci < CI && gco < CO) {
        __pipeline_memcpy_async(dst, &mW(gci, gco, kd, kh, kw), sizeof(T));
      } else {
        *dst = T(0);
      }
    }
  };
  // Prologue: stage the first chunk.
  stage_load(0, 0);
  __pipeline_commit();
  int buf = 0;
  for (int ci0 = 0; ci0 < CI; ci0 += CI_CHUNK) {
    const int ci_next = ci0 + CI_CHUNK;
    // Issue the next chunk's staged loads; they overlap with compute below.
    if (ci_next < CI) {
      stage_load(buf ^ 1, ci_next);
    }
    __pipeline_commit();
    // Wait until the current buffer's async group has landed (the group
    // just issued for the next buffer is allowed to remain in flight).
    __pipeline_wait_prior(1);
    __syncthreads();
    Tensor sX = make_sX(buf);
    Tensor sW = make_sW(buf);
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pvalid[i]) continue;
      #pragma unroll
      for (int kd = 0; kd < K; ++kd) {
        int sd = ld[i] + (K - 1) - kd;
        #pragma unroll
        for (int kh = 0; kh < K; ++kh) {
          int sh = lh[i] + (K - 1) - kh;
          #pragma unroll
          for (int kw = 0; kw < K; ++kw) {
            int sw = lw[i] + (K - 1) - kw + woff;
            #pragma unroll
            for (int ci = 0; ci < CI_CHUNK; ++ci) {
              float xv = (float)sX(ci, sd, sh, sw);
              #pragma unroll
              for (int co = 0; co < CO_TILE; ++co) {
                acc[co][i] += xv * (float)sW(ci, co, kd, kh, kw);
              }
            }
          }
        }
      }
    }
    __syncthreads();
    buf ^= 1;
  }

  #pragma unroll
  for (int co = 0; co < CO_TILE; ++co) {
    int gco = co0 + co;
    if (gco >= CO) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pvalid[i]) continue;
      int od = d0 + ld[i];
      int oh = h0 + lh[i];
      int ow = w0 + lw[i];
      mY(gco, od, oh, ow) = static_cast<T>(acc[co][i]);
    }
  }
}

torch::Tensor convtranspose3d_k3s1_forward(torch::Tensor x,
                                           torch::Tensor w,
                                           c10::optional<torch::Tensor> b) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) {
    TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  }

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) {
    TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  }

  TORCH_CHECK(x.dim() == 5, "x must be [N, CI, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [CI, CO, KD, KH, KW] for ConvTranspose3d groups=1");

  const int64_t N   = x.size(0);
  const int64_t CI  = x.size(1);
  const int64_t D   = x.size(2);
  const int64_t H   = x.size(3);
  const int64_t Wid = x.size(4);

  TORCH_CHECK(w.size(0) == CI, "w.size(0) must equal in_channels");
  const int64_t CO = w.size(1);
  TORCH_CHECK(w.size(2) == 3 && w.size(3) == 3 && w.size(4) == 3,
              "custom CUTE kernel currently implements kernel_size = 3");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == CO, "bias must be [out_channels]");
    b_ptr = b_c.data_ptr<float>();
  }

  // stride=1, padding=0, dilation=1, output_padding=0, kernel=3
  const int64_t Dout = D + 2;
  const int64_t Hout = H + 2;
  const int64_t Wout = Wid + 2;

  auto y = torch::empty({N, CO, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 256;
  constexpr int TD = 8;
  constexpr int TH = 8;
  constexpr int TW = 8;
  constexpr int CO_TILE = 4;

  const int64_t ntd = (Dout + TD - 1) / TD;
  const int64_t nth = (Hout + TH - 1) / TH;
  const int64_t ntw = (Wout + TW - 1) / TW;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)(ntd * nth * ntw),
      (unsigned)((CO + CO_TILE - 1) / CO_TILE),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  convtranspose3d_k3s1_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)CI, (int)CO,
      (int)D, (int)H, (int)Wid,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "convtranspose3d_k3s1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
