class ModelNew(nn.Module):
    """
    ConvTranspose3d implemented with one custom cooperative-tiled CUTE/CUDA kernel.
    Optimized for the provided configuration: square 3x3x3 kernel, stride=1,
    padding=0, output_padding=0, dilation=1, groups=1.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = int(groups)
        self.use_bias = bool(bias)

        # Keep the same parameter names/initialization as the reference module.
        self.conv_transpose3d = nn.ConvTranspose3d(
            self.in_channels,
            self.out_channels,
            (self.kernel_size, self.kernel_size, self.kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
