                "ModelNew custom CUTE kernel supports only kernel_size=3, stride=1, "
                "padding=0, output_padding=0, dilation=1, groups=1."
            )

        bias = self.conv_transpose3d.bias if self.conv_transpose3d.bias is not None else None
        return self._ext.convtranspose3d_k3s1_forward(
            x,
            self.conv_transpose3d.weight,
            bias,
        )
